"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1094-06-15:0":{"b": ["Էլ Սիդը տիրացավ Վալենսիային. հիմնվեց Վալենսիայի (Էլ Սիդի) իշխանությունը", "f5b81beb"], "d": ["Ռոդրիգո Դիաս դե Վիվարը (Էլ Սիդ), պաշարումից հետո, 1094 թ. հունիսի 15-ին վերցրեց Վալենսիայի վերահսկողությունը. կադիության պաշտոնում թողեց Իբն Ջահհաֆին։ Վալենսիան, դուրս գալով «Մուլուք ալ-Թավաիֆ» (Անդալուսիայի թայֆա ամիրայություններ) գրառումից, անցավ Վալենսիայի (Էլ Սիդի) իշխանությանը։", "e51445ac"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-01-01:0":{"b": ["Ալմորավիդները գրավեցին Վալենսիան", "ce05cefc"], "d": ["1099 թ. Ռոդրիգոյի մահից հետո նրա կին Խիմենայի ձեռքին գտնվող Վալենսիան 1102 թ. գրավվեց Ալմորավիդների կողմից։", "8407a408"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-05-05:0":{"b": ["Վալենսիան գրավվեց Ալմորավիդների կողմից (1102)", "833a9c9a"], "d": ["1099 թ. Էլ Սիդի մահից հետո քաղաքը մնացել էր նրա այրի Խիմենային. Վալենսիան 1102 թ. գրավվեց Ալմորավիդների կողմից։ Վալենսիան այս թվականին Վալենսիայի (Էլ Սիդի) իշխանությունից դուրս գալով անցնում է Ալմորավիդների պետությանը։", "a9ecdc4d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1106-09-04:0":{"b": ["Յուսուֆ բ. Թաշֆինը մահացավ Մարաքեշում. նրան հաջորդեց որդի Ալի բ. Յուսուֆը", "3a60ecd3"], "d": ["Յուսուֆ բ. Թաշֆինը մահացավ Մարաքեշում. նրան հաջորդեց որդի Ալի բ. Յուսուֆը", "3a60ecd3"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1108-01-01:0":{"b": ["Ալի բ. Յուսուֆը Ուկլեսում հաղթանակ տարավ քրիստոնեական բանակի դեմ (501, 1108)։", "8380cd9c"], "d": ["Ալի բ. Յուսուֆը Ուկլեսում հաղթանակ տարավ քրիստոնեական բանակի դեմ (501, 1108)։", "8380cd9c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1110-01-24:0":{"b": ["Հուդյան ամիրա Ահմեդ ալ-Մուստաինը մահացավ. Ալմորավիդյան բանակը շարժվեց դեպի Սարագոսա", "8378eeaf"], "d": ["Ահմեդ ալ-Մուստաին Բիլլահի մահից (1 Ռաջաբ 503 / 1110 թ. հունվարի 24) հետո Ալմորավիդյան մի բանակ Վալենսիայից շարժվեց դեպի Սարագոսա։", "1303f83d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1112-06-28:0":{"b": ["Ալի բ. Յուսուֆը պաշարեց Տոլեդոն, բայց չկարողացավ վերցնել", "d35d4a4e"], "d": ["Ալի բ. Յուսուֆի Անդալուսիա երկրորդ անցման ժամանակ Տոլեդոն պաշարվեց. ուժեղ դիմադրության պատճառով պաշարումը վերացվեց (506/1112-13), փոխարենը գրավվեցին Մադրիդը և շրջակա որոշ կենտրոններ։", "106302f2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1118-12-19:0":{"b": ["Արագոնի թագավոր Ալֆոնսո I-ը մտավ Սարագոսա. քաղաքը Ալմորավիդներից անցավ Արագոնին", "49a4a80d"], "d": ["Երկարատև պաշարման ավարտին պարենը սպառված Սարագոսան 1118 թ. դեկտեմբերի 11-ին ընդունեց հանձնման պայմանները. Ալֆոնսո I-ը դեկտեմբերի 18-ին մտավ քաղաք։ Սարագոսան դարձավ Արագոնի թագավորության մայրաքաղաքը։", "25de2b0c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1121-11-13:0":{"b": ["Իբն Թումարթը հռչակեց իր մահդիությունը", "33dad2aa"], "d": ["Ալմորավիդների մայրաքաղաք Մարաքեշից վտարվելուց հետո Իբն Թումարթը, կողմնակիցներ հավաքելով, 515 թվականի Ռամադանին (1121 թ. նոյեմբեր) հռչակեց իր մահդիությունը. Դերեն լեռներում սկսվեց Ալմոհադների շարժումը։", "67c9ea64"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1127-01-01:0":{"b": ["Արագոնի թագավորը պաշարեց Գրանադան, բայց ետ քաշվեց", "60877b49"], "d": ["Գրանադայի քրիստոնյաների դրդմամբ Արագոնի թագավորը պաշարեց քաղաքը. ուժգին պաշտպանության պատճառով 1127 թ. ստիպված եղավ ետ քաշվել։", "1684bbe7"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1132-01-01:0":{"b": ["Կաստիլիայի թագավոր Ալֆոնսո VII-ը կողոպտեց Սևիլիան", "23664808"], "d": ["Ալֆոնսո VII-ը 526 (1132) թվականին կողոպտեց Սևիլիան. Ալմորավիդների քաղաքի կուսակալը սպանվեց կռիվներում։", "342ff94a"]},
