"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0883-07-11:0":{"b": ["Մուհամմեդը մահացավ. նրա հորեղբայր Ալ-Յասա II-ը անցավ ամիրայության գլուխ (270, 883)։", "1a21eeb6"], "d": ["Մուհամմեդը մահացավ. նրա հորեղբայր Ալ-Յասա II-ը անցավ ամիրայության գլուխ (270, 883)։", "1a21eeb6"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0903-07-01:0":{"b": ["Կարմաթները պաշարեցին Դամասկոսը. առաջնորդ Սահիբ ուն-Նաքա Յահյան սպանվեց պաշարման ժամանակ", "9b876cc8"], "d": ["Զիքրավայհ իբն Միհրավայհի որդիներից Սահիբ ուն-Նաքա մականունով հայտնի Յահյան 290 թվականի Շաաբանին (903 թվականի հուլիս) սպանվեց Դամասկոսի պաշարման ժամանակ. նրան փոխարինեց եղբայրը՝ Սահիբ ուշ-Շամման, և Հալեպի վրա անհաջող հարձակումից հետո գրավեց Համան, Հոմսը, Մաարրաթ ան-Նուամանը և Բաալբեկը։", "9980a87c"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0906-01-01:0":{"b": ["Կարմաթական դաի Աբու Ղանիմը, Բուսրան, Տիբերիան և Հիթը թալանելուց հետո, մտավ Քուֆա. կարճ ժամանակում վտարվեց", "7b175ddd"], "d": ["Զիքրավայհի կողմից Բանու Քալբի մեջ կարմաթականությունը վերակենդանացնելու համար ուղարկված Աբու Ղանիմ Աբդուլլահ իբն Սաիդը և նրա մարդիկ, թալանելով Բուսրա, Ադրիաթ, Տիբերիա, Հիթ և նման բնակավայրեր, հարձակվեցին Դամասկոսի վրա. հաջողության չհասնելով՝ մտան Քուֆա, բայց կարճ ժամանակում վտարվեցին քաղաքից (293/906)։", "e62c81d1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0911-01-01:0":{"b": ["Տուրֆանի ույղուրական պետությունը դարձավ անկախ", "d48689ad"], "d": ["Տուրֆանի ույղուրական պետությունը դարձավ անկախ", "d48689ad"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0913-01-01:0":{"b": ["Աբու Սաիդ ալ-Ջաննաբին սպանվեց Ուբայդուլլահ ալ-Մահդիի կազմակերպած մահափորձով (301). պետությունը շարունակեցին որդիները։", "dd507fc0"], "d": ["Աբու Սաիդ ալ-Ջաննաբին սպանվեց Ուբայդուլլահ ալ-Մահդիի կազմակերպած մահափորձով (301). պետությունը շարունակեցին որդիները։", "dd507fc0"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0931-01-24:0":{"b": ["Աբու Թահիրը Բահրեյնի կառավարումը հանձնեց մի իրանցու, որին ներկայացնում էր որպես մահդի. նոր մահդին ութսուն օր անց սպանվեց", "1816f4a5"], "d": ["Օմանը գրաված (318/930) Աբու Թահիր ալ-Ջաննաբին հաջորդ տարի Բահրեյնի կառավարումը հանձնեց Սպահանից բերել տված և ժողովրդին որպես մահդի ներկայացրած մի իրանցու։ Երբ իրանցին իրեն ներկայացրեց որպես հին Իրանի խոսրովների սերնդից և իրանական կրոնի բարեփոխիչ ու արաբների դեմ գաղափարներ առաջ քաշեց, պաշտոնի կարգվելուց ութսուն օր անց Աբու Թահիրի կողմից սպանվեց. դա Բահրեյնի կարմաթների մեջ մեծ շփոթ ու ցրվածություն առաջացրեց։", "919b72ac"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0935-01-01:0":{"b": ["Մարդավիջը Սպահանում սպանվում է թուրք զինվորների կողմից. նրան փոխարինում է եղբայր Վուշմգիրը (323/935)։", "11355262"], "d": ["Մարդավիջը Սպահանում սպանվում է թուրք զինվորների կողմից. նրան փոխարինում է եղբայր Վուշմգիրը (323/935)։", "11355262"]},
